import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

const root = process.cwd();

const fontEntries = [
  ['interRegularBase64', 'src/assets/fonts/Inter-Regular.ttf'],
  ['interSemiBoldBase64', 'src/assets/fonts/Inter-SemiBold.ttf'],
  ['interBoldBase64', 'src/assets/fonts/Inter-Bold.ttf'],
];

const lines = [
  '// Generated by scripts/generate-pdf-fonts.mjs',
  '// Do not edit manually.',
  '',
];

for (const [exportName, relativePath] of fontEntries) {
  const filePath = resolve(root, relativePath);
  const base64 = readFileSync(filePath).toString('base64');
  lines.push(`export const ${exportName} = '${base64}';`);
}

lines.push('');

writeFileSync(resolve(root, 'src/assets/fonts/interPdfFonts.ts'), `${lines.join('\n')}`);
